<?php
return [
 'appointments'=>['title'=>'Appointments and agent contacts','sql'=>"SELECT a.id,a.kind,a.status,a.starts_at,p.title property,requester.name requester,requester.phone requester_phone,agent.name agent,agent.phone agent_phone,agent.public_id agent_id,a.otp_verified_at FROM appointments a JOIN properties p ON p.id=a.property_id JOIN users requester ON requester.id=a.requested_by LEFT JOIN users agent ON agent.id=a.assigned_to ORDER BY a.starts_at DESC,a.id DESC"],
 'service_orders'=>['title'=>'Orders and handoffs','sql'=>"SELECT o.id,o.kind,o.status,o.scheduled_at,customer.name customer,customer.phone customer_phone,provider.name provider,provider.phone provider_phone,p.title property,(SELECT SUM(quantity*(unit_price+installation_cost)) FROM order_items WHERE order_id=o.id) total FROM orders o JOIN users customer ON customer.id=o.user_id JOIN users provider ON provider.id=o.provider_id JOIN tenancies t ON t.id=o.tenancy_id JOIN properties p ON p.id=t.property_id ORDER BY o.id DESC"],
 'catering'=>['title'=>'Catering delivery roster','sql'=>"SELECT s.id,s.status,m.name plan,m.meal,s.people,s.starts_on,s.ends_on,u.name customer,u.phone customer_phone,p.business_name provider,s.tenancy_id FROM meal_subscriptions s JOIN meal_plans m ON m.id=s.meal_plan_id JOIN provider_profiles p ON p.user_id=m.provider_id JOIN users u ON u.id=s.user_id ORDER BY s.id DESC"],
 'verification'=>['title'=>'Document register','sql'=>"SELECT d.id,d.original_name,d.kind,d.status,u.name account,u.public_id,u.phone,d.tenancy_id,d.property_id,r.name reviewer,d.created_at FROM documents d JOIN users u ON u.id=d.user_id LEFT JOIN users r ON r.id=d.reviewed_by ORDER BY d.id DESC"],
 'inspection_reports'=>['title'=>'Inspection register','sql'=>"SELECT i.id,p.title property,i.kind,i.status,i.summary,u.name agent,u.phone agent_phone,r.name reviewer,i.inspected_at,(SELECT COUNT(*) FROM inspection_rooms WHERE inspection_id=i.id) rooms FROM inspections i JOIN properties p ON p.id=i.property_id JOIN users u ON u.id=i.agent_id LEFT JOIN users r ON r.id=i.approved_by ORDER BY i.id DESC"],
 'support'=>['title'=>'Support and callbacks','sql'=>"SELECT s.id,s.category,s.subject,s.message,s.status,s.contact_channel,u.name account,u.phone,r.name assigned_to,s.created_at FROM support_tickets s JOIN users u ON u.id=s.user_id LEFT JOIN users r ON r.id=s.assigned_to ORDER BY s.id DESC"],
 'campaigns'=>['title'=>'Campaign outreach','sql'=>"SELECT c.id,c.name,c.starts_on,c.ends_on,l.name area,u.name field_agent,u.phone agent_phone,k.completed_on,k.owner_name,k.owner_phone,k.checklist FROM campaigns c JOIN locations l ON l.id=c.location_id LEFT JOIN campaign_assignments a ON a.campaign_id=c.id LEFT JOIN users u ON u.id=a.user_id LEFT JOIN campaign_checklists k ON k.campaign_id=c.id AND k.user_id=a.user_id ORDER BY c.id DESC,k.id DESC"],
 'reviews'=>['title'=>'Customer feedback','sql'=>"SELECT r.id,r.rating,r.comment,u.name author,s.name reviewed_account,r.tenancy_id,r.request_id,r.order_id,r.created_at FROM reviews r JOIN users u ON u.id=r.author_id JOIN users s ON s.id=r.subject_id ORDER BY r.id DESC"],
 'referrals'=>['title'=>'Referral register','sql'=>"SELECT r.id,u.name referrer,u.public_id,r.referred_email,r.status,v.name registered_friend,r.created_at FROM referrals r JOIN users u ON u.id=r.referrer_id LEFT JOIN users v ON v.id=r.referred_user_id ORDER BY r.id DESC"],
 'accounts'=>['title'=>'Accounts and permissions','sql'=>"SELECT u.id,u.public_id,u.name,u.email,u.phone,u.status,u.deleted_at,u.verified_at,(SELECT GROUP_CONCAT(r.name) FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=u.id) roles FROM users u ORDER BY u.id"],
 'rent_roll'=>['title'=>'Rent roll by property','sql'=>"SELECT p.id property_id,p.title,u.name tenant,t.rent,t.utility_charge,t.advance_paid,t.status FROM tenancies t JOIN properties p ON p.id=t.property_id JOIN users u ON u.id=t.head_tenant_id ORDER BY p.id"],
 'monthly_dues'=>['title'=>'Monthly balance by tenant','sql'=>"SELECT u.public_id,u.name,i.period,i.total,i.paid,i.balance,i.status FROM v_invoice_balances i JOIN users u ON u.id=i.user_id ORDER BY i.period DESC,u.name"],
 'full_address'=>['title'=>'Every exact property address','sql'=>"SELECT id,title,division,district,area,sub_area,road_no,house_no,house_name,floor_no,flat_no,latitude,longitude FROM v_property_locations ORDER BY id"],
 'cost_reconciliation'=>['title'=>'Maintenance cost reconciliation','sql'=>'SELECT * FROM v_cost_reconciliation ORDER BY request_id DESC'],
 'payment_trail'=>['title'=>'Payment approval trail','sql'=>"SELECT p.id,p.invoice_id,p.amount,p.method,p.reference,p.status,r.name reviewer,f.name confirmer,p.created_at,p.confirmed_at FROM payments p LEFT JOIN users r ON r.id=p.reviewed_by LEFT JOIN users f ON f.id=p.confirmed_by ORDER BY p.id DESC"],
 'provider_jobs'=>['title'=>'Provider work and customer details','sql'=>"SELECT m.id,m.title,m.status,m.pay_later,c.name category,provider.name provider,tenant.name tenant,m.appointment_at FROM maintenance_requests m JOIN service_categories c ON c.id=m.category_id JOIN tenancies t ON t.id=m.tenancy_id JOIN users tenant ON tenant.id=m.requested_by LEFT JOIN users provider ON provider.id=m.provider_id ORDER BY m.id DESC"],
 'move_out'=>['title'=>'Move-out and inspection schedule','sql'=>"SELECT t.id,t.move_out_date,DATE_SUB(t.move_out_date,INTERVAL 3 DAY) inspection_due,p.title,u.name tenant FROM tenancies t JOIN properties p ON p.id=t.property_id JOIN users u ON u.id=t.head_tenant_id WHERE t.status='notice'"],
 'story_coverage'=>['title'=>'User story implementation coverage','sql'=>'SELECT id,persona,want_to,module,related_tables,implementation_status FROM user_stories ORDER BY id'],
 'owner_income'=>['title'=>'Owner income across properties','sql'=>"SELECT u.id,u.name,COUNT(DISTINCT p.id) property_count,COALESCE(SUM(t.rent),0) monthly_rent FROM users u JOIN properties p ON p.owner_id=u.id LEFT JOIN tenancies t ON t.property_id=p.id AND t.status IN('active','notice') GROUP BY u.id,u.name"],
 'relationships'=>['title'=>'Primary and foreign key relationships','sql'=>"SELECT TABLE_NAME,COLUMN_NAME,CONSTRAINT_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME,CONSTRAINT_NAME"]
];
